package com.hau.exam.application;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import com.hau.exam.application.port.out.*;import com.hau.exam.application.service.ExamGenerationService;import com.hau.exam.domain.exception.*;import com.hau.exam.domain.model.*;import java.time.*;import java.util.*;import org.junit.jupiter.api.*;
class ExamGenerationServiceTest{ExamRepository exams=mock(ExamRepository.class);ExamMatrixRepository matrices=mock(ExamMatrixRepository.class);ExamTemplateRepository templates=mock(ExamTemplateRepository.class);QuestionCatalogPort questions=mock(QuestionCatalogPort.class);ExamGenerationService service=new ExamGenerationService(exams,matrices,templates,questions,Clock.systemUTC());UUID subject=UUID.randomUUID(),chapter=UUID.randomUUID();ExamMatrix matrix;Actor admin=new Actor(UUID.randomUUID(),Role.SUBJECT_ADMIN,"CNTT","token");@BeforeEach void set(){var rule=new ExamMatrixRule(UUID.randomUUID(),chapter,null,Difficulty.EASY,2);matrix=new ExamMatrix(UUID.randomUUID(),"M","CNTT",subject,2,List.of(rule),admin.userId(),Instant.now(),Instant.now());when(matrices.findById(matrix.id())).thenReturn(Optional.of(matrix));when(exams.save(any())).thenAnswer(i->i.getArgument(0));}
@Test void insufficientApprovedQuestionsFailsClearly(){when(questions.approvedQuestions(anyString(),any(),any(),isNull(),any(),anyString())).thenReturn(List.of(candidate(UUID.randomUUID(),"APPROVED")));assertThrows(InsufficientQuestionsException.class,()->service.generate("E",matrix.id(),null,admin));}@Test void nonApprovedQuestionsAreNeverSelected(){when(questions.approvedQuestions(anyString(),any(),any(),isNull(),any(),anyString())).thenReturn(List.of(candidate(UUID.randomUUID(),"DRAFT"),candidate(UUID.randomUUID(),"APPROVED")));assertThrows(InsufficientQuestionsException.class,()->service.generate("E",matrix.id(),null,admin));}@Test void generatedVersionIsConsistent(){when(questions.approvedQuestions(anyString(),any(),any(),isNull(),any(),anyString())).thenReturn(List.of(candidate(UUID.randomUUID(),"APPROVED"),candidate(UUID.randomUUID(),"APPROVED")));var e=service.generate("E",matrix.id(),null,admin);assertEquals(1,e.versions().getFirst().versionNumber());assertEquals(2,e.versions().getFirst().questions().size());}@Test void facultyViolationRejected(){assertThrows(ForbiddenException.class,()->service.generate("E",matrix.id(),null,new Actor(UUID.randomUUID(),Role.SUBJECT_ADMIN,"KT","token")));}private QuestionCatalogPort.QuestionCandidate candidate(UUID id,String status){return new QuestionCatalogPort.QuestionCandidate(id,"CNTT",subject,chapter,null,Difficulty.EASY,status);}}
